import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { afterEach, beforeEach, describe, expect, it } from 'vitest';

// #3801: the sibling test mocks child_process, so it could not see that the
// grep pattern was rejected by assertSafeShellArg() before grep ever ran and
// the hook had been a silent no-op in production. This test runs the REAL
// grep on a real temp fixture: three importers of ./util/b in the same
// subtree, then a Write to src/util/b.ts. Every block condition holds, so the
// only acceptable answer is a block. A control with a single importer must
// stay silent, which proves the block is the detector's, not a crash.

import { parseGrepRef, staleImportDetector } from '../../posttool/write/stale-import-detector.js';
import { createTestContext } from '../fixtures/test-context.js';
import type { HookInput } from '../../types.js';

let proj: string;

function fixture(importers: number): void {
  mkdirSync(join(proj, 'src', 'util'), { recursive: true });
  mkdirSync(join(proj, 'tests'), { recursive: true });
  writeFileSync(join(proj, 'src', 'util', 'b.ts'), 'export const x = 1;\n');
  for (let i = 0; i < importers; i++) {
    writeFileSync(join(proj, 'src', `importer${i}.ts`), "import { x } from './util/b';\nexport const y = x;\n");
  }
}

function writeInput(): HookInput {
  return {
    tool_name: 'Write',
    session_id: '00000000-0000-4000-8000-000000000000',
    tool_input: { file_path: join(proj, 'src', 'util', 'b.ts'), content: 'export const x = 2;\n' },
  } as HookInput;
}

beforeEach(() => {
  proj = mkdtempSync(join(tmpdir(), 'stale-import-real.'));
});
afterEach(() => {
  rmSync(proj, { recursive: true, force: true });
});

describe('staleImportDetector with the real grep (#3801)', () => {
  it('blocks when three same-subtree importers reference the rewritten module', () => {
    fixture(3);
    const result = staleImportDetector(writeInput(), createTestContext({ projectDir: proj }));
    expect(result.continue).toBe(false);
    expect(result.stopReason).toMatch(/Stale imports detected for b\.ts \(3 references\)/);
  });

  it('stays silent with a single importer (below the signal threshold)', () => {
    fixture(1);
    const result = staleImportDetector(writeInput(), createTestContext({ projectDir: proj }));
    expect(result.continue).toBe(true);
  });

  // #5113: the project dir went through the shell allowlist, so a character
  // outside it threw. A space is that same failure on any platform.
  it('does not throw on a project dir the shell allowlist rejects', () => {
    rmSync(proj, { recursive: true, force: true });
    proj = mkdtempSync(join(tmpdir(), 'stale import real.'));
    fixture(3);
    const result = staleImportDetector(writeInput(), createTestContext({ projectDir: proj }));
    expect(result.stopReason).toMatch(/Stale imports detected for b\.ts \(3 references\)/);
  });
});

describe('parseGrepRef (#5113)', () => {
  it('keeps the drive letter of a Windows path', () => {
    const ref = parseGrepRef("C:\\Users\\RICU\\src\\a.ts:12:import { x } from './b';");
    expect(ref?.file).toContain('C:');
    expect(ref?.line).toBe(12);
    expect(ref?.content).toBe("import { x } from './b';");
  });

  it('still parses a POSIX path', () => {
    expect(parseGrepRef('/repo/src/a.ts:3:import y')).toEqual({
      file: '/repo/src/a.ts',
      line: 3,
      content: 'import y',
    });
  });

  it('rejects a line with no line number', () => {
    expect(parseGrepRef('not a grep line')).toBeNull();
  });
});
